import{Z as t,e as s,f as i,a0 as a}from"./chunks/framework.DmpHOl9T.js";const g=JSON.parse('{"title":"Translating Forms Across Craft Sites","description":"","frontmatter":{},"headers":[],"relativePath":"guides/control-panel-admin/translating-forms-across-craft-sites.md","filePath":"guides/control-panel-admin/translating-forms-across-craft-sites.md","lastUpdated":1782532814000}'),o={name:"guides/control-panel-admin/translating-forms-across-craft-sites.md"};function r(n,e,l,d,h,p){return s(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="translating-forms-across-craft-sites" tabindex="-1">Translating Forms Across Craft Sites <a class="header-anchor" href="#translating-forms-across-craft-sites" aria-label="Permalink to &quot;Translating Forms Across Craft Sites&quot;">​</a></h1><p>Multi-site Craft projects usually need the same form structure everywhere with different wording per site — not a completely different form per language. Formie stores one canonical layout and sparse per-site overrides for translatable text. This walkthrough takes a contact form from English source copy to French overrides without duplicating forms or fighting translation files.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>Craft multi-site enabled with at least two sites</li><li><a href="/forms/multi-site-and-translation">Multi-Site &amp; Translation</a></li><li><a href="/forms/translations">Translations</a> — three layers of text in Formie</li></ul><h2 id="two-separate-concerns" tabindex="-1">Two Separate Concerns <a class="header-anchor" href="#two-separate-concerns" aria-label="Permalink to &quot;Two Separate Concerns&quot;">​</a></h2><p>Keep these distinct:</p><table tabindex="0"><thead><tr><th>Concern</th><th>Question</th><th>Where to configure</th></tr></thead><tbody><tr><td><strong>Site availability</strong></td><td>Should this form exist on this site?</td><td><a href="/forms/form-groups">Form group</a> <strong>Site Policy</strong></td></tr><tr><td><strong>Content translation</strong></td><td>What text should visitors see?</td><td>Form builder <strong>site switcher</strong></td></tr></tbody></table><p>A form can be available on English and French with translated labels. Or available on one regional site only with no translations needed.</p><p>Formie forms are <strong>not</strong> entry-style per-site documents. One field layout, handles, conditions, and integrations are shared. Per-site differences are mostly text.</p><h2 id="step-1-—-scope-the-form-to-the-right-sites" tabindex="-1">Step 1 — Scope the Form to the Right Sites <a class="header-anchor" href="#step-1-—-scope-the-form-to-the-right-sites" aria-label="Permalink to &quot;Step 1 — Scope the Form to the Right Sites&quot;">​</a></h2><p>Create or assign a <a href="/forms/form-groups">form group</a> with the correct <strong>Enabled Sites</strong> and <strong>Site Propagation</strong> before authors build content.</p><p>Example — global contact form on EN and FR:</p><ol><li>Group <strong>Global Forms</strong> with both sites enabled</li><li>Propagation: <strong>All enabled sites</strong></li><li>Create the form on the English (source) site</li></ol><p>Example — Australia-only form:</p><ol><li>Group <strong>Australia Forms</strong> with only Australia enabled</li><li>Create the form while viewing the Australia site in the CP</li></ol><p>Ungrouped forms are treated as available on all sites you can edit.</p><h2 id="step-2-—-build-canonical-copy-on-the-source-site" tabindex="-1">Step 2 — Build Canonical Copy on the Source Site <a class="header-anchor" href="#step-2-—-build-canonical-copy-on-the-source-site" aria-label="Permalink to &quot;Step 2 — Build Canonical Copy on the Source Site&quot;">​</a></h2><p>Each form has a <strong>source site</strong> — where it was created. That site holds default translatable content.</p><ol><li>Switch the CP to the source site (usually your primary English site)</li><li>Open the contact form</li><li>Set title <code>Contact us</code>, field label <code>Your name</code>, success message, button labels</li><li>Save</li></ol><p>Structural work (adding fields, conditions, integrations) updates the <strong>shared canonical form</strong> regardless of which site you are viewing when you save.</p><h2 id="step-3-—-add-french-overrides" tabindex="-1">Step 3 — Add French Overrides <a class="header-anchor" href="#step-3-—-add-french-overrides" aria-label="Permalink to &quot;Step 3 — Add French Overrides&quot;">​</a></h2><ol><li>Use the <strong>site switcher</strong> (globe icon) in the form builder breadcrumb</li><li>Select <strong>French</strong></li><li>Change title to <code>Contactez-nous</code>, field label to <code>Votre nom</code>, and other French copy</li><li>Save</li></ol><p>Only changed keys are stored in <code>formie_form_site_overrides</code>. The English source site defaults stay untouched.</p><p>Translation icons beside field labels indicate overridable values. On the source site you edit the default; on other sites you edit overrides.</p><h2 id="step-4-—-translate-nested-and-option-fields" tabindex="-1">Step 4 — Translate Nested and Option Fields <a class="header-anchor" href="#step-4-—-translate-nested-and-option-fields" aria-label="Permalink to &quot;Step 4 — Translate Nested and Option Fields&quot;">​</a></h2><p><strong>Name, Address, Group, Repeater</strong> — child field labels translate the same way as top-level fields. Override only the children that change.</p><p><strong>Dropdown, radio, checkbox</strong> — override option <strong>labels</strong> and <strong>values</strong> per site when both need to differ. Leave unchanged options inherited from the canonical form.</p><p><strong>Page settings</strong> — submit, back, and save button labels on each page are translatable.</p><p><strong>Form messages</strong> — error, success, limit, and scheduling messages support per-site overrides.</p><h2 id="step-5-—-verify-front-end-rendering" tabindex="-1">Step 5 — Verify Front-End Rendering <a class="header-anchor" href="#step-5-—-verify-front-end-rendering" aria-label="Permalink to &quot;Step 5 — Verify Front-End Rendering&quot;">​</a></h2><p>No extra template code is required. When you render for a site, Formie merges overrides automatically:</p><div class="language-twig vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">twig</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ craft.formie.renderForm(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;contactForm&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) }}</span></span></code></pre></div><p>This applies to:</p><ul><li>Twig rendering</li><li><a href="/graphql/query-forms">GraphQL</a> and headless packages (<code>siteId</code>, <code>locale</code> props)</li><li>React/Vue bootstrap</li></ul><p>Submissions store <code>siteId</code> so you know which site they came from.</p><h2 id="step-6-—-what-not-to-put-in-translation-files" tabindex="-1">Step 6 — What Not to Put in Translation Files <a class="header-anchor" href="#step-6-—-what-not-to-put-in-translation-files" aria-label="Permalink to &quot;Step 6 — What Not to Put in Translation Files&quot;">​</a></h2><p>Form builder content does <strong>not</strong> belong in <code>translations/*/formie.php</code>:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Don’t translate form builder copy here — use CP site overrides instead</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Your name&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Votre nom&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Contact us&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Contactez-nous&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span></code></pre></div><p>Keep <code>formie.php</code> for <strong>Formie-owned UI strings</strong> only:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Plugin UI strings</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;{label} cannot be blank.&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;…&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;(optional)&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;…&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span></code></pre></div><p>See <a href="/forms/translations">Translations</a> for the full split.</p><h2 id="step-7-—-notifications" tabindex="-1">Step 7 — Notifications <a class="header-anchor" href="#step-7-—-notifications" aria-label="Permalink to &quot;Step 7 — Notifications&quot;">​</a></h2><p>Notification subject and body can be edited per site in the builder, with overrides stored alongside other translation data.</p><p>Many teams prefer instead:</p><ul><li><strong>Separate notifications</strong> with <a href="/forms/conditions">conditions</a> per site or language</li><li><strong>Variables</strong> in one notification (<code>{site:name}</code>, and so on)</li></ul><p>See <a href="/guides/email-notifications/multi-site-notification-content">Multi-site notification content</a>.</p><h2 id="when-you-need-different-layouts-per-site" tabindex="-1">When You Need Different Layouts per Site <a class="header-anchor" href="#when-you-need-different-layouts-per-site" aria-label="Permalink to &quot;When You Need Different Layouts per Site&quot;">​</a></h2><p>Site overrides are for <strong>different text on the same form</strong>, not different field sets.</p><p>For radically different forms:</p><ul><li><strong>Separate forms</strong> in groups scoped to the right sites</li><li><strong><a href="/forms/conditions">Conditions</a></strong> to show/hide fields based on site variables</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>French site shows English labels</strong></p><p>Add French site overrides in the builder — not entries in <code>formie.php</code>.</p><p><strong>Two English sites need different labels</strong></p><p>Use CP site overrides. A single <code>translations/en/formie.php</code> cannot distinguish Craft sites.</p><p><strong>Field added on French site appeared on English too</strong></p><p>Structural changes are global. Only text overrides are per-site.</p>`,57)])])}const u=t(o,[["render",r]]);export{g as __pageData,u as default};
